from pathlib import Path
import json,html,textwrap
ROOT=Path(__file__).resolve().parents[1];M=json.loads((ROOT/'modelo/sistema.json').read_text())
BASE='https://app.diagrams.net/?mode=device#Uhttps%3A%2F%2Fraw.githubusercontent.com%2FYutre3%2Fhotel-duerme-bien%2Fmain%2Fdiagramas-editables%2F'
repo='https://github.com/Yutre3/hotel-duerme-bien';site='https://yutre3.github.io/hotel-duerme-bien/'
