columns={'Por hacer':['Validar identificación y reglas de habitación compartida','Validar tarifa y fórmula definitiva de cobro','Validar permisos y condiciones de gestión de reservas','Recibir rúbrica y retroalimentación de Evaluación 1'],'En curso':[],'En revisión':['Informe de requerimientos y entrevista simulada','Casos de uso, procesos y modelo de datos','Sketch, wireframes y mockups','Prueba académica del prototipo'],'Terminado':['Conservar los 11 materiales originales','Reconstruir diagramas nativos y enlazar el editor','Implementar pasajeros individuales y costos','Verificar procesos y publicar la entrega']}
