(ROOT/'planificacion/kanban.json').write_text(json.dumps(kanban,ensure_ascii=False,indent=2))
(ROOT/'planificacion/kanban.md').write_text('# Kanban · Duerme Bien\n\n| Estado | Tarea |\n|---|---|\n'+'\n'.join(f'| {r["estado"]} | {r["tarea"]} |' for r in kanban)+'\n\nTerminado indica trabajo técnico realizado. La revisión académica y la validación del hotel siguen pendientes.\n')
s=(ROOT/'scripts/construir_modelado.py').read_text();exec(s[:s.index('cases={')]);d=D('kanban','Kanban · Duerme Bien',1600,1080)
for i,(state,tasks) in enumerate(columns.items()):
 x=40+i*390;d.node('col'+str(i),state,x,100,360,850,'frame',fill='#edf4f7')
 for j,t in enumerate(tasks):d.node(f'task{i}-{j}','\n'.join(textwrap.wrap(t,29)),x+15,175+j*185,330,150)
 if not tasks:d.node('none','Sin tareas en curso',x+15,175,330,100)
d.save()
