css='''body{font-family:Arial,sans-serif;max-width:1180px;margin:32px auto;padding:0 24px;color:#163b50;line-height:1.6}h1{font-size:32px}h2{border-top:1px solid #d8e2e7;margin-top:45px;padding-top:22px}h3{font-size:21px}a{color:#126479}nav,.links{display:flex;gap:18px;flex-wrap:wrap}.diagram{display:block;max-width:100%;height:auto;border:1px solid #d8e2e7;cursor:zoom-in}.tools{margin:12px 0 32px;display:flex;gap:18px;flex-wrap:wrap}iframe{width:100%;height:1100px;border:1px solid #d8e2e7}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.tile{border:1px solid #d8e2e7;padding:12px}.tile img{max-width:100%;height:auto}.tile h3{margin:0 0 8px}@media(max-width:750px){.grid{grid-template-columns:1fr 1fr}h1{font-size:26px}iframe{height:950px}}'''
page=f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Duerme Bien · Tema 6</title><style>{css}</style></head><body><h1>Sistema de Pasajeros - Hotel Duerme Bien</h1><p>Tema 6 · Luis Huenchul</p><nav><a href="informe/informe-con-diagramas.pdf">Informe completo</a><a href="prototipo/">Prototipo</a><a href="mockups/">Wireframes y mockups</a><a href="{repo}">Repositorio</a></nav><h2>Casos de uso y procesos</h2>'
