 page+=f'<h3>{name}</h3><a href="diagramas/{key}.svg" target="_blank" rel="noopener"><img class="diagram" src="diagramas/{key}.svg" alt="{name}" loading="lazy"></a><p class="tools"><a href="diagramas/{key}.pdf">PDF</a><a href="{edit(key)}" target="_blank" rel="noopener">Editar en diagrams.net</a></p>'
