for key,name in M['pantallas']:
 page+=f'<section class="tile"><h3>{name}</h3><a href="mockups/mockup-{key}.svg" target="_blank" rel="noopener"><img src="mockups/mockup-{key}.svg" alt="Mockup de {name}" loading="lazy"></a><div class="links"><a href="mockups/wireframe-{key}.svg">Wireframe</a><a href="{edit("mockup-"+key)}" target="_blank" rel="noopener">Editar mockup</a></div></section>'
